SELECT ?author ?authorNationality ?authorOccupation ?llewellynOccupation WHERE {
  ?work wdt:P31 wd:Q47461344;  # instance of a play
        rdfs:label "The Long Christmas Dinner"@en;
        wdt:P50 ?author.
  ?author wdt:P27 ?authorNationality;
          wdt:P106 ?authorOccupation.
  VALUES ?authorOccupation {wd:Q6625963 wd:Q36180} # novelist and playwright
  wd:Q532841 wdt:P106 ?llewellynOccupation.  # Richard Llewellyn

  FILTER EXISTS {
    SELECT ?author WHERE {
      ?author rdfs:label "The Long Christmas Dinner"@en.
    }
  }
}
LIMIT 10

SELECT DISTINCT ?actor WHERE {
  ?veteranFilm rdfs:label "The Veteran"@en ;
                dbo:releaseDate ?date ;
                dbo:starring ?actor .
  FILTER(YEAR(?date) = 2011)

  ?fantasyFilm dbo:starring ?actor ;
               dbo:releaseDate ?date2 ;
               dbo:genre ?genre ;
               dbo:basedOn ?game .
  FILTER(YEAR(?date2) = 2016)

  ?genre rdfs:label ?genreLabel .
  FILTER(CONTAINS(LCASE(?genreLabel), "fantasy"))

  ?game dbo:publisher ?publisher .
  ?publisher rdfs:label ?publisherLabel .
  FILTER(CONTAINS(LCASE(?publisherLabel), "enix"))
}

LIMIT 10

SELECT ?author ?hasReceivedPostscripts WHERE {
  VALUES ?authorName {"Peter Francis Straub" "(author name of Hundred Thousand Billion Poems)"}
  ?author rdfs:label ?authorName.
  OPTIONAL {
    ?award a <http://example.org/ontology/Award> ;
           rdfs:label "Postscripts" .
    ?author <http://example.org/ontology/hasReceivedAward> ?award .
  }
  BIND(IF(BOUND(?award), true, false) AS ?hasReceivedPostscripts)
}

SELECT 
  (SELECT COUNT(*) FROM Productions WHERE director = (SELECT director FROM Films WHERE title = 'Matchstick Men' AND genre = 'Comedy')) AS matchstick_men_director_productions,
  (SELECT COUNT(*) FROM Productions WHERE director = 'Elmer Clifton') AS elmer_clifton_productions;

SELECT 
  (SELECT COUNT(*) FROM productions WHERE director = 
      (SELECT director FROM films WHERE title = 'Matchstick Men' AND genre LIKE '%Comedy%')
  ) AS matchstick_men_productions,
  (SELECT COUNT(*) FROM productions WHERE director = 'Elmer Clifton') AS elmer_clifton_productions;

SELECT ?cummingsBirthDate ?musicianBirthDate WHERE {
  ?cummings wdt:P31 wd:Q5;  # instance of human
            rdfs:label "Burton Lorne Cummings"@en;
            wdt:P569 ?cummingsBirthDate.
  ?album wdt:P31 wd:Q7366;  # instance of album
         rdfs:label "Red Book"@en;
         wdt:P175 ?musician.
  ?musician wdt:P569 ?musicianBirthDate.
}
LIMIT 1

{
