SELECT ?individual ?individualCountry ?makarovaCountry WHERE {
  ?tournament rdf:type dbo:SportsEvent ;
              dbo:location dbr:Dallas ;
              dbo:date "1983-06"^^xsd:gYearMonth ;
              dbo:event dbr:Dallas_Open_(tennis) .
  ?match dbo:tournament ?tournament ;
         dbo:participant ?individual ;
         dbo:participant dbr:Steve_Denton ;
         dbo:matchType dbo:Doubles .
  ?individual dbo:birthPlace ?birthPlace .
  ?birthPlace dbo:country ?individualCountry .

  dbr:Ekaterina_Makarova dbo:birthPlace ?makarovaBirthPlace .
  ?makarovaBirthPlace dbo:country ?makarovaCountry .

  FILTER(?individual != dbr:Ekaterina_Makarova)
  FILTER(?individualCountry != ?makarovaCountry)
} LIMIT 1

SELECT ?malePlayer WHERE {
  ?tournamentEvent wdt:P31 wd:Q847017;         # Tennis doubles tournament
                   rdfs:label "1990 Newsweek Champions Cup – Doubles final"@en.
  ?match wdt:P1346 ?tournamentEvent.
  ?team wdt:P1346 ?match;                    # Team participated in match
        wdt:P642 wd:Q847017.
  ?teamMember wdt:P1344 ?team;
              wdt:P106 wd:Q5372.             # Occupation tennis player
  ?teamMember wdt:P641 wd:Q847017.            # Tennis sport
  ?teamMember rdfs:label ?malePlayer.
  ?partner wdt:P1344 ?team; 
           wdt:P641 wd:Q847017;
           rdfs:label "Jim Grabb"@en.
  FILTER (?malePlayer != "Jim Grabb")
} LIMIT 1

SELECT ?film ?filmLabel ?bestSoundNomination WHERE {
  ?film wdt:P161 wd:Q155837; # Steven Seagal as cast member
        wdt:P57 wd:Q5539557. # Directed by J. F. Lawton
  OPTIONAL {
    ?film wdt:P166 ?award .
    ?award wdt:P31 wd:Q19020;   # award instance is Academy Award
           wdt:P580 ?nomination .
    ?award rdfs:label ?awardLabel FILTER(CONTAINS(LCASE(?awardLabel), "best sound"))
  }
  BIND(EXISTS {
    ?film wdt:P166 ?award .
    ?award wdt:P31 wd:Q19020;
           rdfs:label ?awardLabel .
    FILTER(CONTAINS(LCASE(?awardLabel), "best sound"))
  } AS ?bestSoundNomination)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 10

