SELECT ?founder ?founderLabel ?organization ?location WHERE {
  ?organization wdt:P31 wd:Q43229;   # instance of organization
                wdt:P159 ?location;    # location
                wdt:P112 ?founder.     # founder
  ?location rdfs:label "Mary's Harbour"@en.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
LIMIT 10

# Additionally, check for missionary activity:
SELECT ?founder ?founderLabel ?mission WHERE {
  ?founder wdt:P106 wd:Q41955;      # occupation missionary
           wdt:P1409 ?mission.      # notable work or role
  FILTER(CONTAINS(LCASE(str(?mission)), "newfoundland") || CONTAINS(LCASE(str(?mission)), "labrador"))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
LIMIT 10

SELECT ?fordBirthDate ?authorBirthDate ?authorOtherRoles WHERE {
  ?ford wdt:P31 wd:Q5;
        rdfs:label "Aleksander Ford"@en;
        wdt:P569 ?fordBirthDate.

  ?author wdt:P31 wd:Q5;
          rdfs:label ?authorName;
          wdt:P569 ?authorBirthDate;
          wdt:P106 ?authorOtherRole.

  FILTER(CONTAINS(LCASE(?authorName), "crane world") || ?authorName = "Author of Crane World") # this filter is tricky, so identify the author of "Crane World"

  ?work wdt:P31 wd:Q47461344; # Q47461344 is a wikidata entry for literary work
        rdfs:label "Crane World"@en;
        wdt:P50 ?author.
} LIMIT 1

