}

SELECT 
  (SELECT COUNT(DISTINCT job_position) FROM FilmCrewRoles WHERE person_name = 'Chester Erskine') AS ChesterErskineRoles,
  (SELECT COUNT(DISTINCT job_position) FROM FilmCrewRoles WHERE person_name = 'Kay Pollak') AS KayPollakRoles;

SELECT ?birthDateFeyder ?birthDateDirector WHERE {
  ?feyder dbo:birthName "Jacques Feyder"@en;
          dbo:birthDate ?birthDateFeyder.
  ?movie dbo:title "Veena Vaadanam"@en;
         dbo:director ?director.
  ?director dbo:birthDate ?birthDateDirector.
} LIMIT 1

SELECT ?city WHERE {
  ?venue wdt:P31 wd:Q570116;  # instance of music venue (Róisín Dubh)
         rdfs:label "Róisín Dubh"@en;
         wdt:P131 ?city.        # located in the administrative territorial entity city
  ?city wdt:P131 ?region.
  ?region rdfs:label ?regionName.
  FILTER(CONTAINS(LCASE(?regionName), "smyth"))

  OPTIONAL {
    ?person wdt:P31 wd:Q5;      # instance of human (Sean Smyth)
            rdfs:label "Sean Smyth"@en;
            wdt:P19 ?birthPlace.
    ?birthPlace wdt:P131 ?city.
  }
} LIMIT 10

SELECT ?director WHERE {
  ?film wdt:P31 wd:Q11424;  # instance of film
        rdfs:label "Brother Brat"@en;
        wdt:P57 ?director.   # director
  FILTER (?director != wd:Q838764)  # exclude Craig Serling (assuming Q838764 is his Wikidata ID)
  ?director wdt:P106 wd:Q11671.  # occupation animator
}

SELECT ?guestArtist WHERE {
  ?album rdfs:label "Cozy Tapes Vol. 2: Too Cozy"@en.
  ?album dbo:guest ?guestArtist.
  ?guestArtist foaf:name "Frank Ocean"@en.
}

SELECT 
  (SELECT COUNT(*) FROM GrandSlamTitles WHERE Player = 'Jim Pugh' AND Event = 'Mixed Doubles') AS JimPughTitles,
  (SELECT Winner FROM TennisTournaments WHERE Tournament = 'Estoril Open' AND Year = 2015 AND Event = 'Singles') AS EstorilWinner,
  (SELECT COUNT(*) FROM GrandSlamTitles WHERE Player = (
    SELECT Winner FROM TennisTournaments WHERE Tournament = 'Estoril Open' AND Year = 2015 AND Event = 'Singles'
  ) AND Event = 'Mixed Doubles') AS EstorilWinnerMixedDoublesTitles;

SELECT director FROM films WHERE title = 'When You Come Back to Me' AND year = 1953;

SELECT title, year, genre, director, cast FROM films WHERE genre LIKE '%comedy%' AND year = 1962 AND cast LIKE '%[director_name]%';

SELECT name, countries_worked FROM filmmakers WHERE name = '[1962_film_director]' AND countries_worked LIKE '%Spain%' AND countries_worked LIKE '%Mexico%' AND countries_worked LIKE '%France%';

